
alter policy schoolpro_module_permission on public.schoolpro_attendance using (private.schoolpro_module_allowed(school_id,'attendance') or (auth.uid() is not null and coalesce(private.is_active_account(),false) and private.schoolpro_operationally_active(school_id) and exists(select 1 from public.schoolpro_students s where s.id=schoolpro_attendance.student_id and s.school_id=schoolpro_attendance.school_id and (s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=auth.uid() and g.status='active'))))) with check (private.schoolpro_module_allowed(school_id,'attendance'));
create policy "Students read own school subject names" on public.schoolpro_subjects for select to authenticated using (coalesce(private.is_active_account(),false) and private.schoolpro_operationally_active(school_id) and exists(select 1 from public.schoolpro_students s where s.school_id=schoolpro_subjects.school_id and s.user_id=auth.uid()));
create policy "Families read own library loans" on public.schoolpro_library_loans for select to authenticated using (coalesce(private.is_active_account(),false) and private.schoolpro_operationally_active(school_id) and exists(select 1 from public.schoolpro_students s where s.id=schoolpro_library_loans.student_id and s.school_id=schoolpro_library_loans.school_id and (s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=auth.uid() and g.status='active'))));
